import React, { useState } from 'react';
import '../styles/theme.css';

export default function Stock() {
  const [searchQuery, setSearchQuery] = useState('');

  const stockItems = [
    { name: 'Lokwan Wheat (Grade A)', category: 'Wheat / Gehun', bags: 450, quantity: '450.00 Qtl', avgRate: '₹ 2,650 / Qtl', totalValue: '₹ 11,92,500', godown: 'Godown No. 1' },
    { name: 'Sharbati Wheat', category: 'Wheat / Gehun', bags: 280, quantity: '280.50 Qtl', avgRate: '₹ 3,400 / Qtl', totalValue: '₹ 9,53,700', godown: 'Godown No. 2' },
    { name: 'Basmati Rice (1121)', category: 'Rice / Chawal', bags: 310, quantity: '310.00 Qtl', avgRate: '₹ 4,800 / Qtl', totalValue: '₹ 14,88,000', godown: 'Godown No. 1' },
    { name: 'Mandhya / Yellow Maize', category: 'Maize / Makka', bags: 204, quantity: '204.00 Qtl', avgRate: '₹ 2,150 / Qtl', totalValue: '₹ 4,38,600', godown: 'Godown No. 3' }
  ];

  const filteredStock = stockItems.filter(item => 
    item.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    item.category.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div style={{ width: '100%', maxWidth: '1100px', margin: '0 auto', fontFamily: 'Segoe UI, sans-serif' }}>
      
      {/* Header & Quick Stats */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <div>
          <h2 style={{ color: '#1B4D3E', margin: 0, fontSize: '22px' }}>Stock & Inventory Management</h2>
          <p style={{ color: '#718096', fontSize: '13px', margin: '4px 0 0 0' }}>Real-time grain stock, bag counts, and godown valuation.</p>
        </div>
        <button style={primaryBtn}>+ Add Stock Batch</button>
      </div>

      {/* Summary Metrics Row */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '15px', marginBottom: '20px' }}>
        <div style={metricCard}>
          <span style={{ fontSize: '12px', color: '#718096', fontWeight: '600' }}>Total Available Quantity</span>
          <div style={{ fontSize: '20px', fontWeight: 'bold', color: '#1B4D3E' }}>1,244.50 Qtl</div>
        </div>
        <div style={metricCard}>
          <span style={{ fontSize: '12px', color: '#718096', fontWeight: '600' }}>Total Inventory Valuation</span>
          <div style={{ fontSize: '20px', fontWeight: 'bold', color: '#27AE60' }}>₹ 40,72,800</div>
        </div>
        <div style={metricCard}>
          <span style={{ fontSize: '12px', color: '#718096', fontWeight: '600' }}>Active Godowns</span>
          <div style={{ fontSize: '20px', fontWeight: 'bold', color: '#2B6CB0' }}>3 Warehouses</div>
        </div>
      </div>

      {/* Search Input */}
      <div style={{ marginBottom: '20px' }}>
        <input 
          type="text" 
          placeholder="Search by grain name or category..." 
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          style={searchInputStyle}
        />
      </div>

      {/* Inventory Table Container */}
      <div style={{ background: '#FFF', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.04)', border: '1px solid #E2E8F0', overflow: 'hidden' }}>
        
        <div style={tableHeaderStyle}>
          <span style={{ flex: 2, fontWeight: 'bold' }}>Commodity Name</span>
          <span style={{ flex: 1.2, fontWeight: 'bold' }}>Category</span>
          <span style={{ flex: 1, fontWeight: 'bold' }}>Total Qty</span>
          <span style={{ flex: 1, fontWeight: 'bold' }}>Avg Rate</span>
          <span style={{ flex: 1.2, fontWeight: 'bold' }}>Total Value</span>
          <span style={{ flex: 1, fontWeight: 'bold' }}>Godown</span>
        </div>

        {filteredStock.map((item, index) => (
          <div key={index} style={tableRowStyle}>
            <div style={{ flex: 2, display: 'flex', alignItems: 'center', gap: '10px' }}>
              <span style={{ fontSize: '18px' }}>🌾</span>
              <div>
                <div style={{ fontWeight: 'bold', color: '#2D3748', fontSize: '14px' }}>{item.name}</div>
                <div style={{ fontSize: '11px', color: '#718096' }}>{item.bags} Bags stored</div>
              </div>
            </div>
            <div style={{ flex: 1.2, fontSize: '13px', color: '#4A5568' }}>{item.category}</div>
            <div style={{ flex: 1, fontSize: '13px', fontWeight: 'bold', color: '#2D3748' }}>{item.quantity}</div>
            <div style={{ flex: 1, fontSize: '13px', color: '#2B6CB0', fontWeight: '600' }}>{item.avgRate}</div>
            <div style={{ flex: 1.2, fontSize: '13px', fontWeight: 'bold', color: '#27AE60' }}>{item.totalValue}</div>
            <div style={{ flex: 1, fontSize: '12px', background: '#EDF2F7', padding: '4px 8px', borderRadius: '6px', textAlign: 'center', color: '#4A5568', width: 'fit-content', fontWeight: '600' }}>{item.godown}</div>
          </div>
        ))}

      </div>

    </div>
  );
}

const primaryBtn = { background: '#1B4D3E', color: '#FFF', border: 'none', padding: '10px 18px', borderRadius: '8px', fontWeight: 'bold', fontSize: '13px', cursor: 'pointer' };
const metricCard = { background: '#FFF', padding: '16px 20px', borderRadius: '12px', border: '1px solid #E2E8F0', boxShadow: '0 2px 6px rgba(0,0,0,0.02)', display: 'flex', flexDirection: 'column', gap: '4px' };
const searchInputStyle = { width: '100%', padding: '12px 16px', borderRadius: '8px', border: '1px solid #CBD5E0', background: '#FFF', fontSize: '14px', boxSizing: 'border-box', outline: 'none' };
const tableHeaderStyle = { display: 'flex', padding: '14px 20px', background: '#F8FAFC', borderBottom: '1px solid #E2E8F0', fontSize: '12px', color: '#718096', textTransform: 'uppercase', letterSpacing: '0.5px' };
const tableRowStyle = { display: 'flex', alignItems: 'center', padding: '16px 20px', borderBottom: '1px solid #EDF2F7', transition: 'background 0.2s' };
